import { Group, Mesh, MeshStandardNodeMaterial, MeshBasicNodeMaterial, PlaneGeometry, Shape, ExtrudeGeometry, PointLight, Color, SRGBColorSpace } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const ACCENT = '#ff2a38';
  const PAPER  = '#e8ecf2';
  const SURF   = '#0b0b10';

  const group = new Group();
  group.name = 'hub-journal-card-3-label';

  const inner = new Group();
  group.add(inner);

  // ---- Rounded card body (extruded PBR) ----
  const W = 1.6, H = 1.0, R = 0.14;
  const shape = new Shape();
  const x = -W / 2, y = -H / 2;
  shape.moveTo(x + R, y);
  shape.lineTo(x + W - R, y);
  shape.quadraticCurveTo(x + W, y, x + W, y + R);
  shape.lineTo(x + W, y + H - R);
  shape.quadraticCurveTo(x + W, y + H, x + W - R, y + H);
  shape.lineTo(x + R, y + H);
  shape.quadraticCurveTo(x, y + H, x, y + H - R);
  shape.lineTo(x, y + R);
  shape.quadraticCurveTo(x, y, x + R, y);

  const cardGeo = new ExtrudeGeometry(shape, {
    depth: 0.05,
    bevelEnabled: true,
    bevelSize: 0.008,
    bevelThickness: 0.008,
    bevelSegments: 2,
    curveSegments: 6,
  });
  cardGeo.computeVertexNormals();

  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(SURF),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.22,
  });
  const card = new Mesh(cardGeo, cardMat);
  inner.add(card);

  // ---- Image plate (atlas region) ----
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    const plateMat = new MeshStandardNodeMaterial({
      roughness: 0.45,
      metalness: 0.3,
      map: tex,
    });
    const plate = new Mesh(new PlaneGeometry(W * 0.86, H * 0.58), plateMat);
    plate.position.set(0, -0.04, 0.058);
    inner.add(plate);
    inner.userData.plate = plate;
    inner.userData.plateMat = plateMat;
  });

  // ---- Accent edge band ----
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(ACCENT),
    toneMapped: false,
    transparent: true,
    opacity: 0.85,
  });
  const edge = new Mesh(new PlaneGeometry(W * 0.9, 0.035), edgeMat);
  edge.position.set(0, -H / 2 + 0.06, 0.058);
  inner.add(edge);
  const edgeGeo = edge.geometry;

  // ---- Text label (fontAtlas MSDF) ----
  const label = ctx.fontAtlas.createText('Journal 3', {
    fontSize: 39,
    color: PAPER,
    align: 'center',
  });
  label.position.set(0, H / 2 - 0.22, 0.058);
  inner.add(label);
  inner.userData.label = label;

  // ---- Contact shadow ----
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });
  const shadow = new Mesh(new PlaneGeometry(W * 1.35, H * 1.15), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -H / 2 - 0.03, -0.06);
  inner.add(shadow);
  const shadowGeo = shadow.geometry;

  // ---- Rim accent light ----
  const rim = new PointLight(new Color(ACCENT), 0.7, 4.0, 2.0);
  rim.position.set(0.7, 0.5, 0.9);
  inner.add(rim);

  // ---- Entrance: rise-in + weighted-settle ----
  inner.position.y = -0.4;
  inner.scale.setScalar(0.96);
  const intro = gsap.timeline();
  intro
    .to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0)
    .to(inner.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.7, ease: 'power3.out' }, 0)
    .to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });

  // ---- Hover lift (rise-in subtle 0.15) ----
  const hoverIn = gsap.timeline({ paused: true });
  hoverIn
    .to(inner.position, { y: 0.15, duration: 0.7, ease: 'power3.out' }, 0)
    .to(edgeMat, { opacity: 1.0, duration: 0.4 }, 0)
    .to(rim, { intensity: 1.2, duration: 0.4 }, 0);

  const hoverOut = gsap.timeline({ paused: true });
  hoverOut
    .to(inner.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0)
    .to(edgeMat, { opacity: 0.85, duration: 0.4 }, 0)
    .to(rim, { intensity: 0.7, duration: 0.4 }, 0);

  let press = null;

  group.userData.handlers = {
    onPointerEnter: () => hoverIn.play(),
    onPointerLeave: () => hoverOut.play(),
    onClick: () => {
      if (press) press.kill();
      press = gsap.timeline()
        .to(inner.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.in' })
        .to(inner.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.18, ease: 'power3.out' })
        .to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power4.out' });
      ctx.emit('hub-journal.select', { cardId: 'journal-3', source: 'journal-card-3-label' });
    },
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    intro.kill();
    hoverIn.kill();
    hoverOut.kill();
    if (press) press.kill();
    cardGeo.dispose();
    edgeGeo.dispose();
    shadowGeo.dispose();
    cardMat.dispose();
    edgeMat.dispose();
    shadowMat.dispose();
    if (inner.userData.plate) {
      inner.userData.plate.geometry.dispose();
      inner.userData.plateMat.dispose();
    }
    label.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material?.dispose?.();
      }
    });
  };

  return group;
}
